/* @lc app=leetcode id=1632 lang=kotlin */ class Solution { fun find(p: IntArray, x: Int): Int = if (p[x] == x) x else find(p, p[x]).also { p[x] = it } fun matrixRankTransform(matrix: Array<IntArray>): Array<IntArray> = matrix.size.let { m -> matrix[0].size.let { n -> IntArray(m).let { rm -> IntArray(n).let { cm -> Array(m) { IntArray(n) }.also { res -> (0 until m * n).groupBy { matrix[it / n][it % n] }.toSortedMap().values.forEach { g -> IntArray(m + n) { it }.let { p -> g.forEach { k -> p[find(p, k / n)] = find(p, m + k % n) }.let { g.groupBy { find(p, it / n) }.values.forEach { comp -> (comp.maxOf { maxOf(rm[it / n], cm[it % n]) } + 1).let { rk -> comp.forEach { k -> res[k / n][k % n] = rk } } } }.let { g.forEach { k -> res[k / n][k % n].also { rm[k / n] = it }.also { cm[k % n] = it } } } } } } } } } } }